/*
Refactor Goals:
- Fix the upload functionality
- Improve board styling for a "PureRef"-like canvas
- Center the board and add aesthetic border
*/

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Search, Grid } from 'lucide-react';

const colors = {
  primary: '#ff3d7f',
  secondary: '#121212',
  accent: '#00dbdd',
  light: '#ffffff'
};

const ConceptBoard = () => {
  const [conceptArt, setConceptArt] = useState([]);
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    const stored = localStorage.getItem('conceptArt');
    if (stored) setConceptArt(JSON.parse(stored));
  }, []);

  useEffect(() => {
    localStorage.setItem('conceptArt', JSON.stringify(conceptArt));
  }, [conceptArt]);

  const handleUpload = (e) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    Array.from(files).forEach((file) => {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const newItem = {
          id: Date.now(),
          src: ev.target.result,
          position: { x: 200, y: 200 },
          scale: 1
        };
        setConceptArt((prev) => [...prev, newItem]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleWheel = (e) => {
    e.preventDefault();
    const delta = -e.deltaY * 0.001;
    setScale((s) => Math.max(0.1, s + delta));
  };

  const handleMouseDown = (e) => {
    const startX = e.clientX;
    const startY = e.clientY;
    const initialOffset = { ...offset };

    const handleMouseMove = (e) => {
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      setOffset({ x: initialOffset.x + dx, y: initialOffset.y + dy });
    };

    const handleMouseUp = () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div style={{ background: colors.secondary, color: colors.light, minHeight: '100vh', padding: 20 }}>
      <div className="flex justify-between items-center mb-4">
        <h1 className="text-2xl font-bold">Concept Board</h1>
        <div className="flex gap-2">
          <button
            onClick={() => fileInputRef.current.click()}
            className="bg-accent text-white px-4 py-2 rounded flex items-center"
          >
            <Upload className="h-4 w-4 mr-1" /> Upload
          </button>
          <input
            type="file"
            multiple
            ref={fileInputRef}
            onChange={handleUpload}
            className="hidden"
          />
        </div>
      </div>

      <div
        ref={boardRef}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        className="relative overflow-hidden border border-gray-600 rounded-lg mx-auto"
        style={{
          width: '90vw',
          height: '80vh',
          background: '#1c1c1c',
          cursor: 'grab'
        }}
      >
        <div
          style={{
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`,
            transformOrigin: '0 0',
            width: 'max-content',
            height: 'max-content',
            position: 'absolute'
          }}
        >
          {conceptArt.map((item) => (
            <img
              key={item.id}
              src={item.src}
              alt="concept"
              style={{
                position: 'absolute',
                top: item.position.y,
                left: item.position.x,
                maxWidth: '300px',
                borderRadius: '8px'
              }}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default ConceptBoard;
